(() => {
'use strict';
const body = document.body;
const ROLE = body.dataset.role || 'visitor';
const PAGE = body.dataset.page || 'welcome';
const ROOT = body.dataset.root || './';
const KEY = 'EcoPoints2026'; // Clave de demostración solicitada; no es un mecanismo seguro para producción.
const K = {users:'ep_users',session:'ep_session',records:'ep_records',campaigns:'ep_campaigns',centers:'ep_centers',joins:'ep_joins',org:'ep_org'};
const $ = (s,ctx=document)=>ctx.querySelector(s);
const $$ = (s,ctx=document)=>[...ctx.querySelectorAll(s)];
const read = (key, fallback=[]) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const write = (key,value) => localStorage.setItem(key,JSON.stringify(value));
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const moneyless = n => new Intl.NumberFormat('es-BO',{maximumFractionDigits:1}).format(Number(n)||0);
const today = () => new Date().toISOString().slice(0,10);
const img = name => `${ROOT}Imagen/${name}`;
const visitorURL = name => `${ROOT}Barra-Visitante/${name}`;
const citizenURL = name => `${ROOT}Usuario-Registrado/User-ciudadano/${name}`;
const adminURL = name => `${ROOT}Usuario-Registrado/User-administrador/${name}`;
const goLogin = () => { location.href = visitorURL('6-inicio-sesion.html'); };
function toast(message){ const el=$('#toast'); if(!el)return; el.textContent=message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('show'),3200); }
function seed(){
 if(!localStorage.getItem(K.campaigns)) write(K.campaigns,[
  {id:'demo-c1',title:'Jornada de reciclaje comunitario',date:'2026-12-05',place:'Santa Cruz de la Sierra · ubicación de ejemplo',description:'Actividad demostrativa para reunir materiales previamente separados.',materials:'Plástico, papel y cartón',demo:true},
  {id:'demo-c2',title:'Semana de educación ambiental',date:'2026-12-12',place:'Actividad virtual · demostración',description:'Sesiones breves para aprender a preparar los residuos antes de entregarlos.',materials:'Todos los materiales',demo:true}
 ]);
 if(!localStorage.getItem(K.centers)) write(K.centers,[
  {id:'demo-p1',name:'Punto Eco demostrativo 01',zone:'Zona por confirmar',city:'Santa Cruz de la Sierra',materials:'Plástico, papel y cartón',hours:'Horario por confirmar',address:'Ubicación ilustrativa: completar con dirección verificada',demo:true},
  {id:'demo-p2',name:'Punto Eco demostrativo 02',zone:'Zona por confirmar',city:'Santa Cruz de la Sierra',materials:'Vidrio y aluminio',hours:'Horario por confirmar',address:'Ubicación ilustrativa: completar con dirección verificada',demo:true}
 ]);
 if(!localStorage.getItem(K.users)) write(K.users,[]);
 if(!localStorage.getItem(K.records)) write(K.records,[]);
 if(!localStorage.getItem(K.joins)) write(K.joins,[]);
}
function current(){const s=read(K.session,null);if(!s)return null;if(s.role==='citizen')return read(K.users,[]).find(u=>u.email===s.email)||null;return s;}
function session(){return read(K.session,null);}
function materialPoints(record){return Math.round((Number(record.amount)||0)*(record.unit==='kg'?10:1));}
function approvedRecords(email){return read(K.records,[]).filter(r=>r.status==='Aprobado'&&(!email||r.email===email));}
function citizenTotals(email){const rows=approvedRecords(email);return {points:rows.reduce((a,r)=>a+materialPoints(r),0),kg:rows.filter(r=>r.unit==='kg').reduce((a,r)=>a+Number(r.amount||0),0),count:rows.length};}
function authGuard(){if(ROLE==='citizen'&&session()?.role!=='citizen') {goLogin();return false;}if(ROLE==='admin'&&session()?.role!=='admin'){goLogin();return false;}return true;}
function visitorNav(){const links=[['inicio','1-inicio.html','Inicio'],['guia','2-guia-reciclaje.html','Guía de reciclaje'],['acopio','3-puntos-acopio.html','Puntos de acopio'],['campanas','4-campañas.html','Campañas'],['informacion','5-informacion.html','Información']];return `<div class="topbar"><div class="container navwrap"><a class="brand" href="${visitorURL('1-inicio.html')}"><img src="${img('eco-logo.svg')}" alt=""><span>EcoPoints</span></a><button class="mobile-toggle" data-menu-toggle aria-label="Abrir navegación">☰</button><nav class="navlinks" id="navlinks">${links.map(([p,f,t])=>`<a class="${PAGE===p?'active':''}" href="${visitorURL(f)}">${t}</a>`).join('')}</nav><div class="nav-actions"><a class="btn small" href="${visitorURL('6-inicio-sesion.html')}">Iniciar sesión</a></div></div></div>`;}
function accountNav(){const isCitizen=ROLE==='citizen';const links=isCitizen?[
 ['inicio','index.html','⌂','Inicio'],['registrar','2-registrar-reciclaje.html','＋','Registrar reciclaje'],['acopio','3-puntos-acopio.html','⌖','Puntos de acopio'],['puntos','4-mis-puntos.html','★','Mis puntos'],['campanas','5-campañas.html','♧','Campañas'],['impacto','6-mi-impacto.html','↗','Mi impacto'],['historial','7-historial.html','◷','Historial'],['perfil','8-mi-perfil.html','◎','Mi perfil']
 ]:[['inicio','index.html','⌂','Dashboard'],['usuarios','1-usuarios.html','♙','Usuarios'],['campanas','2-campañas.html','♧','Campañas'],['acopio','3-puntos-acopio.html','⌖','Puntos de acopio'],['registros','4-registros-reciclaje.html','▤','Registros'],['estadisticas','5-estadisticas.html','▥','Estadísticas'],['reportes','6-reportes.html','⇩','Reportes'],['configuracion','7-configuracion.html','⚙','Configuración']];
 const home=isCitizen?citizenURL('index.html'):adminURL('index.html');
 return `<div class="topbar"><div class="container navwrap"><a class="brand" href="${home}"><img src="${img('eco-logo.svg')}" alt=""><span>EcoPoints <small style="font:600 .67rem 'DM Sans';color:#6b796e">${isCitizen?'CIUDADANO':'ADMIN'}</small></span></a><button class="mobile-toggle" data-menu-toggle aria-label="Abrir navegación">☰</button><nav class="navlinks" id="navlinks">${links.map(([p,f,ico,t])=>`<a class="${PAGE===p?'active':''}" href="${isCitizen?citizenURL(f):adminURL(f)}">${ico} ${t}</a>`).join('')}</nav><div class="nav-actions"><span class="muted" style="font-size:.83rem">${esc(current()?.name||'Usuario')}</span><button class="btn outline small" data-logout>Cerrar sesión</button></div></div></div>`;
}
function footer(){return `<footer class="footer"><div class="container footer-inner"><div><a class="brand" style="color:#fff" href="${visitorURL('1-inicio.html')}"><img src="${img('eco-logo.svg')}" alt="">EcoPoints</a><p>Pequeñas acciones, grandes cambios.</p></div><div class="footer-links"><a href="${visitorURL('2-guia-reciclaje.html')}">Guía de reciclaje</a><a href="${visitorURL('3-puntos-acopio.html')}">Puntos de acopio</a><a href="${visitorURL('4-campañas.html')}">Campañas</a><a href="${visitorURL('6-inicio-sesion.html')}">Acceso</a></div></div></footer>`;}
function pageHero(kicker,title,desc){return `<section class="page-hero"><div class="container"><span class="kicker">${kicker}</span><h1 class="page-title">${title}</h1><p>${desc}</p></div></section>`;}
function setLayout(content, sidebar=false){$('#page-content').innerHTML=content;}
function sampleCenters(){return read(K.centers,[]);}
function centerCards(){return sampleCenters().map(c=>`<article class="card"><div class="iconbox">📍</div><div style="display:flex;justify-content:space-between;gap:10px;align-items:center;margin-top:12px"><h3>${esc(c.name)}</h3>${c.demo?'<span class="tag gold">Ejemplo</span>':''}</div><p>${esc(c.address)}</p><p><b>Materiales:</b> ${esc(c.materials)}<br><b>Horario:</b> ${esc(c.hours)}<br><b>Zona:</b> ${esc(c.zone||'Por confirmar')}</p></article>`).join('');}
function campaignCards(joinable=false){const rows=read(K.campaigns,[]), joins=read(K.joins,[]), email=current()?.email;return rows.map(c=>`<article class="card campaign-card"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><span class="tag">${esc(c.date)}</span>${c.demo?'<span class="tag gold">Ejemplo</span>':''}</div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="campaign-meta"><span>⌖ ${esc(c.place)}</span><span>♻ ${esc(c.materials||'Participación ambiental')}</span></div>${joinable?`<button class="btn small" data-join-campaign="${esc(c.id)}" ${joins.some(j=>j.id===c.id&&j.email===email)?'disabled':''}>${joins.some(j=>j.id===c.id&&j.email===email)?'Inscrito':'Participar'}</button>`:''}</article>`).join('')||'<div class="empty"><strong>No hay campañas registradas.</strong>Vuelve más adelante para consultar nuevas actividades.</div>';}
function renderWelcome(){return `<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">♻ Reciclaje y participación ambiental</span><h1>Pequeñas acciones.<br><span>Grandes cambios.</span></h1><p>Aprende a separar tus residuos, encuentra lugares de entrega y descubre cómo cada acción puede contribuir a un entorno más limpio.</p><div class="hero-actions"><a class="btn" href="${visitorURL('1-inicio.html')}">Explorar EcoPoints →</a><a class="btn secondary" href="${visitorURL('7-crear-cuenta.html')}">Crear mi cuenta</a></div><div class="stats-strip"><div class="stat-mini"><strong>Aprende</strong><small>Guías claras para separar.</small></div><div class="stat-mini"><strong>Encuentra</strong><small>Consulta puntos de acopio.</small></div><div class="stat-mini"><strong>Participa</strong><small>Registra tus acciones.</small></div></div></div><div class="hero-art"><img src="${img('hero-eco.svg')}" alt="Ilustración de reciclaje, contenedor y naturaleza"></div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Conoce la plataforma</span><h2>Tu camino para reciclar mejor</h2><p>EcoPoints reúne información y herramientas para ayudarte antes, durante y después de reciclar.</p></div></div><div class="grid three"><article class="card"><div class="iconbox">📘</div><h3>Aprende a clasificar</h3><p>Identifica plástico, papel, cartón, vidrio y aluminio, y conoce cómo prepararlos.</p><a class="card-link" href="${visitorURL('2-guia-reciclaje.html')}">Consultar la guía →</a></article><article class="card"><div class="iconbox">📍</div><h3>Encuentra dónde entregar</h3><p>Explora puntos de acopio y revisa qué materiales recibe cada lugar.</p><a class="card-link" href="${visitorURL('3-puntos-acopio.html')}">Ver puntos de acopio →</a></article><article class="card"><div class="iconbox">🌱</div><h3>Mantén el hábito</h3><p>Registra tus actividades, consulta tus avances y participa en campañas.</p><a class="card-link" href="${visitorURL('6-inicio-sesion.html')}">Comenzar ahora →</a></article></div></div></section><section class="section soft"><div class="container two-col"><div><span class="kicker">El valor de tu aporte</span><h2 class="page-title">Haz visible tu compromiso ambiental</h2><p class="muted">Con una cuenta personal puedes guardar tus registros, consultar puntos acumulados y observar tu progreso. Los puntos son un incentivo de participación, no una medida científica del impacto ambiental.</p><a class="btn" href="${visitorURL('7-crear-cuenta.html')}">Crear cuenta ciudadana</a></div><img src="${img('impact.svg')}" alt="Ilustración de impacto ambiental" style="border-radius:22px;width:100%"></div></section>`;}
function renderVisitor(){
 if(PAGE==='welcome') return renderWelcome();
 if(PAGE==='inicio') return `<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">♻ Bienvenido a EcoPoints</span><h1>Reciclar mejor empieza con <span>información clara.</span></h1><p>Conoce cómo separar tus residuos, ubica puntos de acopio y descubre actividades ambientales para participar.</p><div class="hero-actions"><a class="btn" href="2-guia-reciclaje.html">Aprender a reciclar</a><a class="btn secondary" href="3-puntos-acopio.html">Encontrar un punto</a></div></div><div class="hero-art"><img src="${img('hero-eco.svg')}" alt="Ilustración de reciclaje"></div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="kicker">Empieza por aquí</span><h2>Herramientas para tus acciones diarias</h2></div></div><div class="grid three"><article class="card"><div class="iconbox">♻️</div><h3>Guía de reciclaje</h3><p>Consulta qué materiales se pueden separar y cómo prepararlos.</p><a class="card-link" href="2-guia-reciclaje.html">Ver guía →</a></article><article class="card"><div class="iconbox">📍</div><h3>Puntos de acopio</h3><p>Explora información de lugares de entrega.</p><a class="card-link" href="3-puntos-acopio.html">Explorar puntos →</a></article><article class="card"><div class="iconbox">🤝</div><h3>Campañas ambientales</h3><p>Conoce actividades comunitarias y formas de participar.</p><a class="card-link" href="4-campañas.html">Ver campañas →</a></article></div></div></section><section class="section soft"><div class="container two-col"><img src="${img('community.svg')}" alt="Comunidad participando en actividades ambientales"><div><span class="kicker">Participación continua</span><h2 class="page-title">No tienes que hacerlo solo.</h2><p class="muted">Crea tu cuenta para registrar reciclajes, establecer metas y visualizar tus avances.</p><a class="btn" href="7-crear-cuenta.html">Crear cuenta ciudadana</a></div></div></section>`;
 if(PAGE==='guia') return `${pageHero('Aprende','Guía de reciclaje','Busca un material y revisa recomendaciones generales para prepararlo antes de llevarlo a un punto de acopio. La aceptación final depende de cada centro.') }<section class="page-content"><div class="container"><div class="search-row"><input id="material-search" placeholder="Buscar material o residuo..." aria-label="Buscar material"><button class="filter-chip active" data-material-filter="all">Todos</button><button class="filter-chip" data-material-filter="Plástico">Plástico</button><button class="filter-chip" data-material-filter="Papel y cartón">Papel y cartón</button><button class="filter-chip" data-material-filter="Vidrio">Vidrio</button><button class="filter-chip" data-material-filter="Aluminio">Aluminio</button></div><div class="grid two" id="material-grid">${materialsHTML()}</div><div class="notice info" style="margin-top:20px">Antes de entregar un material, consulta las condiciones del punto de acopio: algunos centros tienen requisitos específicos de limpieza, separación o presentación.</div></div></section>`;
 if(PAGE==='acopio') return `${pageHero('Encuentra','Puntos de acopio','Consulta qué materiales recibe cada lugar y verifica su dirección y horario antes de desplazarte. Los puntos actuales son datos ilustrativos para el prototipo.') }<section class="page-content"><div class="container content-stack"><div class="notice"><b>Datos de demostración:</b> los puntos que aparecen a continuación no son establecimientos verificados. Deben reemplazarse por direcciones y horarios confirmados antes de publicar la plataforma.</div><div class="search-row"><input id="center-search" placeholder="Buscar por nombre, ciudad o material..."></div><div class="two-col"><div class="map-placeholder"><div class="map-center"><div class="pin">📍</div><b>Mapa de puntos de acopio</b><div class="muted" style="font-size:.83rem">Vista ilustrativa del prototipo</div></div></div><div class="card"><span class="kicker">Antes de visitar</span><h3>Verifica la información</h3><p>Confirma que el punto esté activo, qué materiales recibe y cuál es su horario actualizado.</p><p class="muted">Los administradores podrán mantener este directorio desde su panel.</p></div></div><div class="grid two" id="center-grid">${centerCards()}</div></div></section>`;
 if(PAGE==='campanas') return `${pageHero('Participa','Campañas ambientales','Conoce actividades y oportunidades para colaborar con otras personas. Para inscribirte y guardar tu participación, crea una cuenta ciudadana.') }<section class="page-content"><div class="container"><div class="notice info" style="margin-bottom:18px">Las actividades señaladas como ejemplo son contenido demostrativo y no representan eventos confirmados.</div><div class="grid two">${campaignCards(false)}</div><div style="margin-top:24px"><a class="btn" href="7-crear-cuenta.html">Crear cuenta para participar</a></div></div></section>`;
 if(PAGE==='informacion') return `${pageHero('Conócenos','Sobre EcoPoints','Una propuesta digital para facilitar la educación, la participación y el seguimiento de acciones de reciclaje.') }<section class="page-content"><div class="container content-stack"><div class="two-col"><div class="card"><span class="kicker">Nuestro propósito</span><h2>Hacer que reciclar sea más sencillo y constante.</h2><p>EcoPoints busca responder a tres barreras: la falta de información para clasificar residuos, el desconocimiento de lugares de entrega y la desmotivación cuando las personas no perciben sus avances.</p></div><img src="${img('community.svg')}" alt="Ilustración de participación comunitaria" style="width:100%;border-radius:20px"></div><div class="grid three"><article class="card"><div class="iconbox">📚</div><h3>Educación</h3><p>Información sencilla para reconocer y preparar materiales reciclables.</p></article><article class="card"><div class="iconbox">📍</div><h3>Acceso</h3><p>Información organizada sobre puntos de acopio y campañas.</p></article><article class="card"><div class="iconbox">🌱</div><h3>Continuidad</h3><p>Herramientas para registrar actividades y visualizar avances.</p></article></div><div class="notice info">EcoPoints es un prototipo académico. La información de campañas, puntos, recompensas y resultados debe validarse antes de operar en un entorno real.</div></div></section>`;
 if(PAGE==='login') return renderLogin();
 if(PAGE==='register') return renderRegister();
 return renderWelcome();
}
const materialData=[['Plástico','🧴','Botellas y envases','Enjuaga los envases, retira restos de contenido y aplástalos cuando sea posible. Verifica el tipo de plástico admitido por el centro.'],['Papel y cartón','📦','Hojas, cajas y cartones','Mantén el material seco y limpio. Retira cintas, restos de comida y elementos que no sean de papel cuando sea posible.'],['Vidrio','🍾','Botellas y frascos','Vacía y enjuaga los recipientes. Manipula con cuidado los envases rotos y consulta si el punto los recibe.'],['Aluminio','🥫','Latas y envases metálicos','Vacía y enjuaga las latas. Aplástalas solo si el centro de acopio lo recomienda.']];
function materialsHTML(){return materialData.map(m=>`<article class="card material-item" data-material="${m[0]}"><div class="material-card"><div class="material-swatch">${m[1]}</div><div><span class="tag">${m[0]}</span><h3 style="margin:7px 0 2px">${m[2]}</h3></div></div><p style="margin-top:12px">${m[3]}</p></article>`).join('');}
function renderLogin(){
 return `<section class="auth-wrap auth-login-page"><div class="container auth-grid">
  <aside class="auth-aside">
   <span class="eyebrow auth-eyebrow">Bienvenido a EcoPoints</span>
   <h2>Tu compromiso con el ambiente comienza aquí.</h2>
   <p>Accede a tu espacio para registrar tus actividades, consultar tus avances o gestionar la plataforma ambiental.</p>
   <img src="${img('hero-eco.svg')}" alt="Ilustración de reciclaje y naturaleza">
  </aside>
  <section class="auth-box">
   <div class="auth-tabs" role="tablist" aria-label="Tipo de acceso">
    <button class="active" type="button" data-auth-tab="citizen-login" role="tab" aria-selected="true">Ciudadano</button>
    <button type="button" data-auth-tab="admin-login" role="tab" aria-selected="false">Administrador</button>
   </div>
   <div class="auth-panel" id="panel-citizen-login" role="tabpanel">
    <div class="auth-heading"><span class="kicker">Cuenta ciudadana</span><h3>Iniciar sesión</h3><p>Ingresa con el correo y la contraseña que registraste.</p></div>
    <form id="citizen-login-form" class="content-stack">
     <div class="field"><label for="login-email">Correo electrónico *</label><input id="login-email" name="email" type="email" required autocomplete="email" placeholder="nombre@correo.com"></div>
     <div class="field"><label for="login-password">Contraseña *</label><input id="login-password" name="password" type="password" required autocomplete="current-password" placeholder="Tu contraseña"></div>
     <div id="login-error" class="help" role="alert"></div>
     <button class="btn auth-submit" type="submit">Ingresar a mi cuenta</button>
    </form>
    <div class="auth-register-cta">
     <div><strong>¿Todavía no tienes una cuenta?</strong><span>Regístrate para guardar tus actividades y consultar tus puntos.</span></div>
     <a class="btn secondary" href="${visitorURL('7-crear-cuenta.html')}">Registrarse</a>
    </div>
   </div>
   <div class="auth-panel" id="panel-admin-login" role="tabpanel" hidden>
    <div class="auth-heading"><span class="kicker">Acceso institucional</span><h3>Acceso administrativo</h3><p>Completa los datos del responsable e introduce la clave asignada a la demostración.</p></div>
    <form id="admin-login-form" class="content-stack">
     <div class="field"><label for="admin-name">Nombre del responsable *</label><input id="admin-name" name="name" required autocomplete="name" placeholder="Nombre completo"></div>
     <div class="field"><label for="admin-email">Correo de contacto *</label><input id="admin-email" name="email" type="email" required autocomplete="email" placeholder="organizacion@correo.com"></div>
     <div class="field"><label for="admin-org">Organización *</label><input id="admin-org" name="organization" required placeholder="Nombre de la organización"></div>
     <div class="field"><label for="admin-key">Clave administrativa *</label><input id="admin-key" name="key" type="password" required autocomplete="current-password" placeholder="Introduce la clave"></div>
     <div id="admin-error" class="help" role="alert"></div>
     <button class="btn auth-submit" type="submit">Entrar al panel administrativo</button>
    </form>
    <div class="notice auth-security-note">Acceso de demostración académica. La clave se valida en el navegador y no representa una protección adecuada para una aplicación publicada.</div>
   </div>
  </section>
 </div></section>`;
}
function renderRegister(){
 return `<section class="auth-wrap auth-register-page"><div class="container auth-grid">
  <aside class="auth-aside">
   <span class="eyebrow auth-eyebrow">Únete a EcoPoints</span>
   <h2>Empieza con una acción. Construye un hábito.</h2>
   <p>Crea tu cuenta para registrar tus reciclajes, encontrar tus avances y participar en actividades ambientales.</p>
   <img src="${img('community.svg')}" alt="Personas participando en acciones ambientales">
   <div class="auth-benefit-list"><span>✓ Guarda tus actividades</span><span>✓ Consulta tus puntos y logros</span><span>✓ Mantén actualizado tu perfil</span></div>
  </aside>
  <section class="auth-box auth-register-box">
   <div class="auth-heading"><span class="kicker">Registro ciudadano</span><h3>Crear cuenta</h3><p>Completa todos los campos obligatorios para configurar tu perfil.</p></div>
   <form id="citizen-register-form" class="form-grid">
    <div class="field full"><label for="reg-name">Nombre completo *</label><input id="reg-name" name="name" required minlength="3" autocomplete="name" placeholder="Nombre y apellidos"></div>
    <div class="field"><label for="reg-email">Correo electrónico *</label><input id="reg-email" name="email" type="email" required autocomplete="email" placeholder="nombre@correo.com"></div>
    <div class="field"><label for="reg-phone">Celular *</label><input id="reg-phone" name="phone" type="tel" required minlength="7" autocomplete="tel" placeholder="Ej. 70000000"></div>
    <div class="field"><label for="reg-city">Ciudad *</label><input id="reg-city" name="city" required autocomplete="address-level2" placeholder="Ej. Santa Cruz de la Sierra"></div>
    <div class="field"><label for="reg-zone">Zona o barrio *</label><input id="reg-zone" name="zone" required autocomplete="address-level3" placeholder="Tu zona o barrio"></div>
    <div class="field"><label for="reg-password">Contraseña *</label><input id="reg-password" name="password" type="password" required minlength="8" autocomplete="new-password" placeholder="Mínimo 8 caracteres"><span class="help">Utiliza al menos 8 caracteres.</span></div>
    <div class="field"><label for="reg-confirm">Confirmar contraseña *</label><input id="reg-confirm" name="confirm" type="password" required minlength="8" autocomplete="new-password" placeholder="Repite tu contraseña"></div>
    <div class="field full"><label for="reg-interests">Materiales que te interesa reciclar</label><select id="reg-interests" name="interests"><option value="Todos los materiales">Todos los materiales</option><option>Plástico</option><option>Papel y cartón</option><option>Vidrio</option><option>Aluminio</option></select></div>
    <div class="field full"><label class="checkline"><input type="checkbox" name="terms" required> Confirmo que los datos son correctos y acepto las condiciones de uso del prototipo.</label></div>
    <div class="field full"><div id="register-error" class="help" role="alert"></div><button class="btn auth-submit" type="submit">Crear mi cuenta</button></div>
   </form>
   <div class="auth-back-link"><span>¿Ya tienes una cuenta?</span><a href="${visitorURL('6-inicio-sesion.html')}">Volver a iniciar sesión</a></div>
   <p class="help auth-form-note">Después de registrarte, encontrarás tus datos en <strong>Mi perfil</strong>, donde podrás modificarlos cuando lo necesites.</p>
  </section>
 </div></section>`;
}function shellCitizen(content){const links=[['inicio','index.html','Inicio'],['registrar','2-registrar-reciclaje.html','Registrar reciclaje'],['acopio','3-puntos-acopio.html','Puntos de acopio'],['puntos','4-mis-puntos.html','Mis puntos'],['campanas','5-campañas.html','Campañas'],['impacto','6-mi-impacto.html','Mi impacto'],['historial','7-historial.html','Historial'],['perfil','8-mi-perfil.html','Mi perfil']];return `${pageHero('Área ciudadana',content.title,content.desc)}<section class="page-content citizen-page"><div class="container page-layout"><aside class="side-card"><h3>Mi espacio</h3><nav class="side-links">${links.map(([p,f,t])=>`<a class="${PAGE===p?'active':''}" href="${citizenURL(f)}">${t}</a>`).join('')}</nav></aside><div class="content-stack">${content.body}</div></div></section>`;}
function renderCitizen(){const u=current()||{},tot=citizenTotals(u.email),records=read(K.records,[]).filter(r=>r.email===u.email),joins=read(K.joins,[]).filter(j=>j.email===u.email);
 if(PAGE==='inicio')return shellCitizen({title:`Hola, ${esc((u.name||'ciudadano').split(' ')[0])} 👋`,desc:'Este es tu espacio para organizar tus actividades de reciclaje y seguir tu progreso.',body:`<div class="metric-grid"><div class="metric"><div class="metric-icon">♻️</div><div class="metric-value">${moneyless(tot.kg)} kg</div><small>Material aprobado</small></div><div class="metric"><div class="metric-icon">★</div><div class="metric-value">${tot.points}</div><small>Puntos acumulados</small></div><div class="metric"><div class="metric-icon">✓</div><div class="metric-value">${tot.count}</div><small>Registros aprobados</small></div><div class="metric"><div class="metric-icon">🤝</div><div class="metric-value">${joins.length}</div><small>Campañas inscritas</small></div></div><div class="two-col"><article class="card"><span class="kicker">Siguiente paso</span><h3>Registra tu próxima actividad</h3><p>Guarda el material, la cantidad y el punto donde realizaste tu entrega. El registro quedará pendiente de validación.</p><a class="btn" href="${citizenURL('2-registrar-reciclaje.html')}">Registrar reciclaje</a></article><article class="card"><span class="kicker">Tu cuenta</span><h3>${esc(u.name||'Mi perfil')}</h3><p>${esc(u.city||'Ciudad no indicada')} · ${esc(u.zone||'Zona no indicada')}</p><p class="muted">Material de interés: ${esc(u.interests||'Todos los materiales')}</p><a class="card-link" href="${citizenURL('8-mi-perfil.html')}">Revisar mi perfil →</a></article></div><div class="card"><div class="section-head"><div><span class="kicker">Participa</span><h3>Próximas campañas</h3></div><a class="card-link" href="${citizenURL('5-campañas.html')}">Ver todas →</a></div><div class="grid two">${campaignCards(true)}</div></div>`});
 if(PAGE==='registrar')return shellCitizen({title:'Registrar reciclaje',desc:'Registra una actividad para llevar seguimiento de los materiales que entregas.',body:`<div class="card"><form id="recycle-form" class="form-grid"><div class="field"><label for="rec-material">Tipo de material *</label><select id="rec-material" name="material" required><option value="">Selecciona</option><option>Plástico</option><option>Papel y cartón</option><option>Vidrio</option><option>Aluminio</option></select></div><div class="field"><label for="rec-amount">Cantidad *</label><input id="rec-amount" name="amount" type="number" min="0.1" step="0.1" required placeholder="Ej. 2.5"></div><div class="field"><label for="rec-unit">Unidad *</label><select id="rec-unit" name="unit"><option value="kg">Kilogramos (kg)</option><option value="unidades">Unidades</option></select></div><div class="field"><label for="rec-date">Fecha de entrega *</label><input id="rec-date" name="date" type="date" max="${today()}" value="${today()}" required></div><div class="field full"><label for="rec-center">Punto de acopio</label><select id="rec-center" name="center"><option value="Entrega por confirmar">Entrega por confirmar</option>${sampleCenters().map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="field full"><label for="rec-note">Observaciones (opcional)</label><textarea id="rec-note" name="note" placeholder="Describe brevemente la actividad o entrega"></textarea></div><div class="field full"><div class="notice info">El registro se guardará como <b>Pendiente</b>. Los puntos se calcularán cuando un administrador valide la actividad.</div></div><div class="field full"><button class="btn" type="submit">Enviar registro</button></div></form></div>`});
 if(PAGE==='acopio')return shellCitizen({title:'Puntos de acopio',desc:'Consulta lugares de entrega. Revisa los datos antes de visitar el establecimiento.',body:`<div class="notice">Los lugares marcados como ejemplo son datos de demostración y no están verificados.</div><div class="map-placeholder"><div class="map-center"><div class="pin">📍</div><b>Directorio de puntos</b><div class="muted" style="font-size:.83rem">Mapa ilustrativo</div></div></div><div class="grid two">${centerCards()}</div>`});
 if(PAGE==='puntos')return shellCitizen({title:'Mis puntos',desc:'Consulta los puntos obtenidos por actividades que fueron validadas.',body:`<div class="metric-grid"><div class="metric"><div class="metric-icon">★</div><div class="metric-value">${tot.points}</div><small>Puntos disponibles</small></div><div class="metric"><div class="metric-icon">♻️</div><div class="metric-value">${tot.count}</div><small>Actividades aprobadas</small></div><div class="metric"><div class="metric-icon">⏳</div><div class="metric-value">${records.filter(r=>r.status==='Pendiente').length}</div><small>En revisión</small></div><div class="metric"><div class="metric-icon">🏅</div><div class="metric-value">${tot.points>=200?'Verde':tot.points>=50?'Semilla':'Inicial'}</div><small>Nivel ilustrativo</small></div></div><div class="card"><h3>Cómo se calculan los puntos</h3><p>En este prototipo, cada kilogramo aprobado equivale a 10 puntos y cada unidad aprobada equivale a 1 punto. La organización puede ajustar estas reglas.</p><div class="notice info">Los puntos son un incentivo de participación. No equivalen directamente a CO₂ evitado ni a otro indicador científico.</div></div>`});
 if(PAGE==='campanas')return shellCitizen({title:'Campañas ambientales',desc:'Explora las actividades disponibles y guarda tu inscripción.',body:`<div class="notice info">Las campañas marcadas como ejemplo son demostrativas; confirma fechas y lugares con la organización.</div><div class="grid two">${campaignCards(true)}</div>`});
 if(PAGE==='impacto')return shellCitizen({title:'Mi impacto',desc:'Visualiza tus aportes registrados y aprobados. Los datos se basan en tu historial.',body:`<div class="two-col"><div class="card"><span class="kicker">Tu contribución</span><div class="metric-value" style="font-family:Manrope;font-size:2.5rem;color:var(--forest)">${moneyless(tot.kg)} kg</div><p>Material aprobado en tus entregas.</p><div class="progress"><span style="width:${Math.min(100,tot.kg/20*100)}%"></span></div><small class="muted">Meta ilustrativa: 20 kg registrados.</small></div><img src="${img('impact.svg')}" alt="Ilustración de crecimiento e impacto" style="width:100%;border-radius:20px"></div><div class="grid two">${materialData.map(m=>{const kg=approvedRecords(u.email).filter(r=>r.material===m[0]&&r.unit==='kg').reduce((a,r)=>a+Number(r.amount||0),0);const units=approvedRecords(u.email).filter(r=>r.material===m[0]&&r.unit==='unidades').reduce((a,r)=>a+Number(r.amount||0),0);return `<div class="card material-card"><div class="material-swatch">${m[1]}</div><div><b>${m[0]}</b><div class="muted">${moneyless(kg)} kg · ${moneyless(units)} unidades</div></div></div>`}).join('')}</div><div class="notice info">Este panel muestra cantidades declaradas y aprobadas en la plataforma. No estima equivalencias ambientales sin una metodología validada.</div>`});
 if(PAGE==='historial')return shellCitizen({title:'Historial de actividades',desc:'Revisa el estado de los registros que has enviado.',body:`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Material</th><th>Cantidad</th><th>Punto de acopio</th><th>Estado</th><th>Puntos</th></tr></thead><tbody>${records.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.material)}</td><td>${moneyless(r.amount)} ${esc(r.unit)}</td><td>${esc(r.center)}</td><td><span class="badge-state ${r.status==='Aprobado'?'ok':''}">${esc(r.status)}</span></td><td>${r.status==='Aprobado'?materialPoints(r):'—'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><strong>Aún no tienes actividades.</strong>Cuando registres tu primer reciclaje, aparecerá aquí.</div></td></tr>'}</tbody></table></div>`});
 if(PAGE==='perfil')return shellCitizen({title:'Mi perfil',desc:'Tus datos personales y preferencias aparecen aquí. Puedes actualizarlos cuando lo necesites.',body:`<div class="card"><div class="profile-header"><div class="avatar">${esc((u.name||'U').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div><div><h3 style="margin:0">${esc(u.name)}</h3><div class="muted">Miembro desde ${esc((u.createdAt||'').slice(0,10)||'—')}</div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><form id="profile-form" class="form-grid"><div class="field full"><label for="profile-name">Nombre completo *</label><input id="profile-name" name="name" value="${esc(u.name)}" required minlength="3"></div><div class="field"><label for="profile-email">Correo electrónico *</label><input id="profile-email" name="email" type="email" value="${esc(u.email)}" required></div><div class="field"><label for="profile-phone">Celular *</label><input id="profile-phone" name="phone" type="tel" value="${esc(u.phone)}" required></div><div class="field"><label for="profile-city">Ciudad *</label><input id="profile-city" name="city" value="${esc(u.city)}" required></div><div class="field"><label for="profile-zone">Zona o barrio *</label><input id="profile-zone" name="zone" value="${esc(u.zone)}" required></div><div class="field full"><label for="profile-interests">Material de interés</label><select id="profile-interests" name="interests">${['Todos los materiales','Plástico','Papel y cartón','Vidrio','Aluminio'].map(v=>`<option ${u.interests===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><div id="profile-message" class="help"></div><button class="btn" type="submit">Guardar cambios del perfil</button></div></form></div><div class="card"><h3>Cambiar contraseña</h3><p>Por seguridad, confirma tu contraseña actual antes de establecer una nueva.</p><form id="password-form" class="form-grid"><div class="field"><label for="old-password">Contraseña actual</label><input id="old-password" name="old" type="password" required></div><div class="field"><label for="new-password">Nueva contraseña</label><input id="new-password" name="next" type="password" minlength="8" required></div><div class="field full"><div id="password-message" class="help"></div><button class="btn secondary" type="submit">Actualizar contraseña</button></div></form></div><div class="notice">El prototipo guarda los datos en el almacenamiento local de este navegador. No se sincronizan entre dispositivos ni sustituyen una base de datos segura.</div>`});
 return shellCitizen({title:'Mi espacio',desc:'Selecciona una sección del menú para continuar.',body:'<div class="card">Bienvenido a EcoPoints.</div>'});
}
function shellAdmin(content){const links=[['inicio','index.html','Dashboard'],['usuarios','1-usuarios.html','Usuarios'],['campanas','2-campañas.html','Campañas'],['acopio','3-puntos-acopio.html','Puntos de acopio'],['registros','4-registros-reciclaje.html','Registros'],['estadisticas','5-estadisticas.html','Estadísticas'],['reportes','6-reportes.html','Reportes'],['configuracion','7-configuracion.html','Configuración']];return `${pageHero('Área administrativa',content.title,content.desc)}<section class="page-content admin-page"><div class="container page-layout"><aside class="side-card"><h3>Administración</h3><nav class="side-links">${links.map(([p,f,t])=>`<a class="${PAGE===p?'active':''}" href="${adminURL(f)}">${t}</a>`).join('')}</nav></aside><div class="content-stack">${content.body}</div></div></section>`;}
function renderAdmin(){const users=read(K.users,[]),records=read(K.records,[]),campaigns=read(K.campaigns,[]),centers=read(K.centers,[]),approved=records.filter(r=>r.status==='Aprobado');
 if(PAGE==='inicio')return shellAdmin({title:'Panel de control',desc:'Resumen de la actividad registrada en esta instalación de EcoPoints.',body:`<div class="metric-grid"><div class="metric"><div class="metric-icon">♙</div><div class="metric-value">${users.length}</div><small>Ciudadanos registrados</small></div><div class="metric"><div class="metric-icon">♻️</div><div class="metric-value">${approved.filter(r=>r.unit==='kg').reduce((a,r)=>a+Number(r.amount||0),0).toFixed(1)}</div><small>Kilogramos aprobados</small></div><div class="metric"><div class="metric-icon">⏳</div><div class="metric-value">${records.filter(r=>r.status==='Pendiente').length}</div><small>Registros pendientes</small></div><div class="metric"><div class="metric-icon">📅</div><div class="metric-value">${campaigns.length}</div><small>Campañas registradas</small></div></div><div class="two-col"><div class="card"><span class="kicker">Pendientes de revisión</span><h3>Validar actividades</h3><p>Revisa los registros enviados por ciudadanos y aprueba únicamente aquellos que cumplan con los criterios de la organización.</p><a class="btn" href="${adminURL('4-registros-reciclaje.html')}">Revisar registros</a></div><div class="card"><span class="kicker">Administración</span><h3>Gestiona la información</h3><p>Actualiza campañas, puntos de acopio y reportes para mantener la plataforma útil y confiable.</p><a class="btn secondary" href="${adminURL('2-campañas.html')}">Gestionar campañas</a></div></div><div class="card"><div class="section-head"><div><span class="kicker">Últimos movimientos</span><h3>Registros recientes</h3></div><a class="card-link" href="${adminURL('4-registros-reciclaje.html')}">Ver todos →</a></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Material</th><th>Cantidad</th><th>Estado</th></tr></thead><tbody>${records.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.email)}</td><td>${esc(r.material)}</td><td>${moneyless(r.amount)} ${esc(r.unit)}</td><td><span class="badge-state ${r.status==='Aprobado'?'ok':''}">${esc(r.status)}</span></td></tr>`).join('')||'<tr><td colspan="5">Todavía no hay registros.</td></tr>'}</tbody></table></div></div>`});
 if(PAGE==='usuarios')return shellAdmin({title:'Usuarios registrados',desc:'Consulta los perfiles ciudadanos y sus datos de contacto.',body:`<div class="notice info">La información corresponde a las cuentas creadas en este mismo navegador. Protege los datos personales y utiliza esta vista solo con autorización.</div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Celular</th><th>Ciudad</th><th>Zona</th><th>Registro</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.phone)}</td><td>${esc(u.city)}</td><td>${esc(u.zone)}</td><td>${esc((u.createdAt||'').slice(0,10))}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><strong>No hay ciudadanos registrados.</strong>Las cuentas creadas desde el formulario aparecerán aquí.</div></td></tr>'}</tbody></table></div>`});
 if(PAGE==='campanas')return shellAdmin({title:'Gestión de campañas',desc:'Crea y administra actividades ambientales que se mostrarán a los ciudadanos.',body:`<div class="card"><h3>Nueva campaña</h3><form id="admin-campaign-form" class="form-grid"><div class="field full"><label for="camp-title">Nombre de la campaña *</label><input id="camp-title" name="title" required></div><div class="field"><label for="camp-date">Fecha *</label><input id="camp-date" name="date" type="date" required></div><div class="field"><label for="camp-place">Lugar *</label><input id="camp-place" name="place" required></div><div class="field"><label for="camp-materials">Materiales o temática</label><input id="camp-materials" name="materials" placeholder="Ej. Plástico, papel"></div><div class="field full"><label for="camp-description">Descripción *</label><textarea id="camp-description" name="description" required></textarea></div><div class="field full"><button class="btn" type="submit">Publicar campaña</button></div></form></div><div class="grid two">${campaigns.map(c=>`<article class="card"><div style="display:flex;justify-content:space-between;gap:8px"><span class="tag">${esc(c.date)}</span>${c.demo?'<span class="tag gold">Ejemplo</span>':''}</div><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="campaign-meta">${esc(c.place)} · ${esc(c.materials||'')}</div>${c.demo?'<p class="help">Contenido inicial de demostración.</p>':`<button class="btn danger small" data-delete-campaign="${esc(c.id)}">Eliminar campaña</button>`}</article>`).join('')}</div>`});
 if(PAGE==='acopio')return shellAdmin({title:'Puntos de acopio',desc:'Mantén actualizado el directorio de lugares donde se reciben materiales.',body:`<div class="card"><h3>Agregar punto de acopio</h3><form id="admin-center-form" class="form-grid"><div class="field"><label for="center-name">Nombre del punto *</label><input id="center-name" name="name" required></div><div class="field"><label for="center-city">Ciudad *</label><input id="center-city" name="city" required></div><div class="field"><label for="center-zone">Zona *</label><input id="center-zone" name="zone" required></div><div class="field"><label for="center-hours">Horario *</label><input id="center-hours" name="hours" required></div><div class="field full"><label for="center-address">Dirección completa *</label><input id="center-address" name="address" required></div><div class="field full"><label for="center-materials">Materiales que recibe *</label><input id="center-materials" name="materials" required placeholder="Plástico, papel, vidrio..."></div><div class="field full"><button class="btn" type="submit">Guardar punto</button></div></form></div><div class="grid two">${centers.map(c=>`<article class="card"><div style="display:flex;justify-content:space-between;gap:8px"><span class="tag">${esc(c.city)}</span>${c.demo?'<span class="tag gold">Ejemplo</span>':''}</div><h3>${esc(c.name)}</h3><p>${esc(c.address)}</p><p><b>Materiales:</b> ${esc(c.materials)}<br><b>Horario:</b> ${esc(c.hours)}<br><b>Zona:</b> ${esc(c.zone)}</p>${c.demo?'<p class="help">Sustituye este registro por información verificada.</p>':`<button class="btn danger small" data-delete-center="${esc(c.id)}">Eliminar punto</button>`}</article>`).join('')}</div>`});
 if(PAGE==='registros')return shellAdmin({title:'Registros de reciclaje',desc:'Valida los envíos de los ciudadanos para actualizar sus puntos.',body:`<div class="notice">Aprueba un registro solo después de comprobar la información o la evidencia según las reglas de tu organización.</div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Ciudadano</th><th>Material</th><th>Cantidad</th><th>Punto</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.email)}</td><td>${esc(r.material)}</td><td>${moneyless(r.amount)} ${esc(r.unit)}</td><td>${esc(r.center)}</td><td><span class="badge-state ${r.status==='Aprobado'?'ok':''}">${esc(r.status)}</span></td><td>${r.status==='Pendiente'?`<button class="btn small" data-review-record="${esc(r.id)}" data-status="Aprobado">Aprobar</button> <button class="btn danger small" data-review-record="${esc(r.id)}" data-status="Rechazado">Rechazar</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7"><div class="empty"><strong>No hay registros enviados.</strong>Los registros de los ciudadanos aparecerán aquí.</div></td></tr>'}</tbody></table></div>`});
 if(PAGE==='estadisticas'){const kg=approved.filter(r=>r.unit==='kg').reduce((a,r)=>a+Number(r.amount||0),0);const byMat=materialData.map(m=>({name:m[0],value:approved.filter(r=>r.material===m[0]&&r.unit==='kg').reduce((a,r)=>a+Number(r.amount||0),0)}));const max=Math.max(1,...byMat.map(x=>x.value));return shellAdmin({title:'Estadísticas',desc:'Indicadores calculados a partir de registros aprobados y cuentas locales.',body:`<div class="metric-grid"><div class="metric"><div class="metric-value">${users.length}</div><small>Usuarios</small></div><div class="metric"><div class="metric-value">${moneyless(kg)} kg</div><small>Kilogramos aprobados</small></div><div class="metric"><div class="metric-value">${approved.length}</div><small>Registros aprobados</small></div><div class="metric"><div class="metric-value">${records.filter(r=>r.status==='Pendiente').length}</div><small>Pendientes</small></div></div><div class="card"><h3>Materiales registrados (kg)</h3>${byMat.map(x=>`<div style="margin:18px 0"><div style="display:flex;justify-content:space-between"><b>${x.name}</b><span>${moneyless(x.value)} kg</span></div><div class="progress"><span style="width:${x.value/max*100}%"></span></div></div>`).join('')}</div><div class="notice info">Estas estadísticas dependen de registros ingresados y validados en el prototipo. No representan datos reales de una ciudad ni equivalencias de impacto ambiental.</div>`});}
 if(PAGE==='reportes')return shellAdmin({title:'Reportes',desc:'Descarga datos de cuentas y registros para análisis interno.',body:`<div class="grid two"><article class="card"><div class="iconbox">📊</div><h3>Reporte de reciclaje</h3><p>Exporta los registros de reciclaje con su estado de validación.</p><button class="btn" data-export="records">Descargar CSV de registros</button></article><article class="card"><div class="iconbox">♙</div><h3>Reporte de usuarios</h3><p>Exporta los datos básicos de los perfiles registrados.</p><button class="btn secondary" data-export="users">Descargar CSV de usuarios</button></article></div><div class="notice">Los archivos pueden contener datos personales. Descárgalos y compártelos únicamente con autorización.</div>`});
 if(PAGE==='configuracion'){const org=read(K.org,{name:'Organización ambiental',email:'',city:'Santa Cruz de la Sierra'});return shellAdmin({title:'Configuración',desc:'Actualiza la información visible de la organización responsable.',body:`<div class="card"><h3>Datos de la organización</h3><form id="org-form" class="form-grid"><div class="field full"><label for="org-name">Nombre de la organización *</label><input id="org-name" name="name" value="${esc(org.name)}" required></div><div class="field"><label for="org-email">Correo de contacto</label><input id="org-email" name="email" type="email" value="${esc(org.email)}"></div><div class="field"><label for="org-city">Ciudad</label><input id="org-city" name="city" value="${esc(org.city)}"></div><div class="field full"><button class="btn" type="submit">Guardar configuración</button></div></form></div><div class="notice">La clave administrativa de este prototipo es fija y se valida en el navegador. No se puede modificar desde aquí. Para un sistema real debe gestionarse en un servidor con usuarios, permisos y recuperación segura de acceso.</div>`});}
 return shellAdmin({title:'Administración',desc:'Selecciona una sección del menú.',body:'<div class="card">Panel EcoPoints</div>'});
}
function renderLoginTabs(tab){$$('[data-auth-tab]').forEach(b=>{const active=b.dataset.authTab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});['citizen-login','admin-login'].forEach(t=>{const p=$(`#panel-${t}`);if(p)p.hidden=t!==tab;});}
async function hashPassword(value){const data=new TextEncoder().encode(value);if(window.crypto?.subtle){const digest=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('');}return btoa(unescape(encodeURIComponent(value)));}
function csvDownload(filename,rows){const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href);}
function start(){seed();if(!authGuard())return;$('#site-header').innerHTML=ROLE==='visitor'?visitorNav():accountNav();$('#site-footer').innerHTML=footer();let content=ROLE==='visitor'?renderVisitor():ROLE==='citizen'?renderCitizen():ROLE==='admin'?renderAdmin():renderWelcome();setLayout(content);}
start();

// Mobile navigation and page interactions.
document.addEventListener('click',e=>{
 const tab=e.target.closest('[data-auth-tab]');if(tab){renderLoginTabs(tab.dataset.authTab);return;}
 if(e.target.closest('[data-menu-toggle]')){$('#navlinks')?.classList.toggle('open');return;}
 if(e.target.closest('[data-logout]')){localStorage.removeItem(K.session);goLogin();return;}
 const join=e.target.closest('[data-join-campaign]');if(join){const s=session();if(s?.role!=='citizen'){goLogin();return;}const joins=read(K.joins,[]);if(!joins.some(j=>j.id===join.dataset.joinCampaign&&j.email===s.email)){joins.push({id:join.dataset.joinCampaign,email:s.email,date:today()});write(K.joins,joins);join.textContent='Inscrito';join.disabled=true;toast('Tu participación quedó registrada en este navegador.');}return;}
 const review=e.target.closest('[data-review-record]');if(review){const rows=read(K.records,[]),r=rows.find(x=>x.id===review.dataset.reviewRecord);if(r){r.status=review.dataset.status; r.reviewedAt=today();write(K.records,rows);toast(`Registro ${r.status.toLowerCase()}.`);setTimeout(()=>location.reload(),350);}return;}
 const delCamp=e.target.closest('[data-delete-campaign]');if(delCamp){write(K.campaigns,read(K.campaigns,[]).filter(x=>x.id!==delCamp.dataset.deleteCampaign));location.reload();return;}
 const delCenter=e.target.closest('[data-delete-center]');if(delCenter){write(K.centers,read(K.centers,[]).filter(x=>x.id!==delCenter.dataset.deleteCenter));location.reload();return;}
 const exp=e.target.closest('[data-export]');if(exp){if(exp.dataset.export==='records'){csvDownload('ecopoints-registros.csv',[['Fecha','Correo','Material','Cantidad','Unidad','Punto','Estado'],...read(K.records,[]).map(r=>[r.date,r.email,r.material,r.amount,r.unit,r.center,r.status])]);}else{csvDownload('ecopoints-usuarios.csv',[['Nombre','Correo','Celular','Ciudad','Zona','Material de interés','Fecha de registro'],...read(K.users,[]).map(u=>[u.name,u.email,u.phone,u.city,u.zone,u.interests,u.createdAt])]);}toast('Se generó el archivo CSV.');}
});
document.addEventListener('input',e=>{
 if(e.target.id==='material-search'){const q=e.target.value.toLowerCase();$$('.material-item').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q));}
 if(e.target.id==='center-search'){const q=e.target.value.toLowerCase();$$('#center-grid .card').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q));}
});
document.addEventListener('click',e=>{const filter=e.target.closest('[data-material-filter]');if(filter){$$('[data-material-filter]').forEach(b=>b.classList.toggle('active',b===filter));$$('.material-item').forEach(card=>card.hidden=filter.dataset.materialFilter!=='all'&&card.dataset.material!==filter.dataset.materialFilter);}});
document.addEventListener('submit',async e=>{
 const form=e.target;
 if(form.id==='citizen-login-form'){e.preventDefault();const fd=new FormData(form),email=String(fd.get('email')).trim().toLowerCase(),password=await hashPassword(String(fd.get('password'))),u=read(K.users,[]).find(x=>x.email===email&&x.passwordHash===password);if(!u){$('#login-error').textContent='No se encontró una cuenta con esos datos. Revisa tu correo y contraseña.';return;}write(K.session,{role:'citizen',email:u.email,name:u.name});location.href=citizenURL('index.html');}
 if(form.id==='citizen-register-form'){e.preventDefault();const fd=new FormData(form),name=String(fd.get('name')).trim(),email=String(fd.get('email')).trim().toLowerCase(),password=String(fd.get('password')),confirm=String(fd.get('confirm'));const err=$('#register-error');if(password!==confirm){err.textContent='Las contraseñas no coinciden.';return;}if(password.length<8){err.textContent='La contraseña debe tener al menos 8 caracteres.';return;}const users=read(K.users,[]);if(users.some(u=>u.email===email)){err.textContent='Ya existe una cuenta con ese correo electrónico.';return;}const user={id:crypto.randomUUID?.()||String(Date.now()),name,email,phone:String(fd.get('phone')).trim(),city:String(fd.get('city')).trim(),zone:String(fd.get('zone')).trim(),interests:String(fd.get('interests')),passwordHash:await hashPassword(password),createdAt:new Date().toISOString()};users.push(user);write(K.users,users);write(K.session,{role:'citizen',email:user.email,name:user.name});toast('Cuenta creada correctamente.');location.href=citizenURL('index.html');}
 if(form.id==='admin-login-form'){e.preventDefault();const fd=new FormData(form);if(String(fd.get('key'))!==KEY){$('#admin-error').textContent='La clave administrativa no es correcta.';return;}const admin={role:'admin',name:String(fd.get('name')).trim(),email:String(fd.get('email')).trim().toLowerCase(),organization:String(fd.get('organization')).trim()};write(K.session,admin);write(K.org,{name:admin.organization,email:admin.email,city:'Santa Cruz de la Sierra'});location.href=adminURL('index.html');}
 if(form.id==='recycle-form'){e.preventDefault();const fd=new FormData(form),rows=read(K.records,[]),s=session();rows.push({id:crypto.randomUUID?.()||String(Date.now()),email:s.email,material:String(fd.get('material')),amount:Number(fd.get('amount')),unit:String(fd.get('unit')),date:String(fd.get('date')),center:String(fd.get('center')),note:String(fd.get('note')),status:'Pendiente',createdAt:new Date().toISOString()});write(K.records,rows);form.reset();toast('Registro enviado. Está pendiente de validación.');setTimeout(()=>location.href=citizenURL('7-historial.html'),700);}
 if(form.id==='profile-form'){e.preventDefault();const fd=new FormData(form),users=read(K.users,[]),s=session(),u=users.find(x=>x.email===s.email),email=String(fd.get('email')).trim().toLowerCase();if(users.some(x=>x.email===email&&x.id!==u.id)){ $('#profile-message').textContent='Ese correo ya está asociado a otra cuenta.';return;}u.name=String(fd.get('name')).trim();u.email=email;u.phone=String(fd.get('phone')).trim();u.city=String(fd.get('city')).trim();u.zone=String(fd.get('zone')).trim();u.interests=String(fd.get('interests'));const activityRecords=read(K.records,[]);activityRecords.forEach(r=>{if(r.email===s.email)r.email=email;});write(K.records,activityRecords);const campaignJoins=read(K.joins,[]);campaignJoins.forEach(j=>{if(j.email===s.email)j.email=email;});write(K.joins,campaignJoins);write(K.users,users);write(K.session,{role:'citizen',email:u.email,name:u.name});$('#profile-message').textContent='Tus datos se actualizaron correctamente.';toast('Perfil actualizado.');}
 if(form.id==='password-form'){e.preventDefault();const fd=new FormData(form),users=read(K.users,[]),s=session(),u=users.find(x=>x.email===s.email),oldHash=await hashPassword(String(fd.get('old')));if(u.passwordHash!==oldHash){$('#password-message').textContent='La contraseña actual no coincide.';return;}if(String(fd.get('next')).length<8){$('#password-message').textContent='La nueva contraseña debe tener al menos 8 caracteres.';return;}u.passwordHash=await hashPassword(String(fd.get('next')));write(K.users,users);form.reset();$('#password-message').textContent='La contraseña se actualizó correctamente.';}
 if(form.id==='admin-campaign-form'){e.preventDefault();const fd=new FormData(form),rows=read(K.campaigns,[]);rows.push({id:crypto.randomUUID?.()||String(Date.now()),title:String(fd.get('title')).trim(),date:String(fd.get('date')),place:String(fd.get('place')).trim(),materials:String(fd.get('materials')).trim(),description:String(fd.get('description')).trim(),demo:false});write(K.campaigns,rows);location.reload();}
 if(form.id==='admin-center-form'){e.preventDefault();const fd=new FormData(form),rows=read(K.centers,[]);rows.push({id:crypto.randomUUID?.()||String(Date.now()),name:String(fd.get('name')).trim(),city:String(fd.get('city')).trim(),zone:String(fd.get('zone')).trim(),hours:String(fd.get('hours')).trim(),address:String(fd.get('address')).trim(),materials:String(fd.get('materials')).trim(),demo:false});write(K.centers,rows);location.reload();}
 if(form.id==='org-form'){e.preventDefault();const fd=new FormData(form);write(K.org,{name:String(fd.get('name')).trim(),email:String(fd.get('email')).trim(),city:String(fd.get('city')).trim()});toast('Configuración guardada.');}
});
})();
